#define BEM_PRECISION_NO_MAIN
#include "validate_bem_real_precision.cu"
#include <cstdint>
#include <chrono>
struct __attribute__((packed)) Header{char magic[8];uint32_t version;uint64_t n;uint32_t nf,nodes,steps;};
static double median(std::vector<double>v){std::sort(v.begin(),v.end());return v[v.size()/2];}
template<class F>static std::vector<double>timing(F f,int warm,int reps){for(int i=0;i<warm;i++)f();cudaDeviceSynchronize();cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);std::vector<double>v;for(int i=0;i<reps;i++){cudaEventRecord(a);f();cudaEventRecord(b);cudaEventSynchronize(b);float x;cudaEventElapsedTime(&x,a,b);v.push_back(x);}cudaEventDestroy(a);cudaEventDestroy(b);return v;}
int main(int argc,char**argv){std::string file,out="results_raw/bem_precision_perf";size_t maxn=SIZE_MAX;for(int i=1;i<argc;i++){if(!strcmp(argv[i],"--dataset"))file=argv[++i];else if(!strcmp(argv[i],"--out"))out=argv[++i];else if(!strcmp(argv[i],"--max-n"))maxn=strtoull(argv[++i],0,10);}FILE*f=fopen(file.c_str(),"rb");Header h;if(!f||fread(&h,1,sizeof h,f)!=sizeof h||memcmp(h.magic,"BEMREAL2",8))return 2;size_t source_n=h.n,n=std::min(maxn,source_n);std::vector<double>buf(source_n*5);std::vector<unsigned char>flags(source_n);if(fread(buf.data(),sizeof(double),buf.size(),f)!=buf.size())return 3;fread(flags.data(),1,flags.size(),f);fclose(f);std::vector<Case>c(n);for(size_t i=0;i<n;i++)c[i]={buf[i],buf[source_n+i],buf[2*source_n+i],buf[4*source_n+i],0,int(i%51%17),0,0};Case*d;Out*o;cudaMalloc(&d,n*sizeof(Case));cudaMalloc(&o,n*sizeof(Out));cudaMemcpy(d,c.data(),n*sizeof(Case),cudaMemcpyHostToDevice);std::filesystem::create_directories(out);std::ofstream s(out+"/bem_precision_performance.csv"),raw(out+"/bem_precision_performance_repetitions.csv");s<<"method,n,kernel_median_ms,e2e_median_ms,correction_fraction,nonfinite,checksum\n";raw<<"method,timing_kind,repetition,value_ms\n";const char*names[]={"fp32","fp32_df32_refine","fp64","adaptive","df32_adaptive"};std::vector<Out>ho(n);cudaHostRegister(c.data(),n*sizeof(Case),0);cudaHostRegister(ho.data(),n*sizeof(Out),0);auto heat_start=std::chrono::steady_clock::now();do{kernel<<<int((n+255)/256),256>>>(d,o,n,2);cudaDeviceSynchronize();}while(std::chrono::duration<double>(std::chrono::steady_clock::now()-heat_start).count()<45);int order[]={2,0,4,1,3};for(int z=0;z<5;z++){int m=order[z];auto kt=timing([&]{kernel<<<int((n+255)/256),256>>>(d,o,n,m);},10,30);auto et=timing([&]{cudaMemcpyAsync(d,c.data(),n*sizeof(Case),cudaMemcpyHostToDevice);kernel<<<int((n+255)/256),256>>>(d,o,n,m);cudaMemcpyAsync(ho.data(),o,n*sizeof(Out),cudaMemcpyDeviceToHost);},10,30);kernel<<<int((n+255)/256),256>>>(d,o,n,m);cudaMemcpy(ho.data(),o,n*sizeof(Out),cudaMemcpyDeviceToHost);size_t corr=0,nf=0;double sum=0;for(size_t i=0;i<n;i++){corr+=ho[i].path==2&&(m==3||m==4);nf+=!ho[i].ok;sum+=ho[i].root*(1+i%17);}for(int i=0;i<30;i++){raw<<names[m]<<",kernel,"<<i<<','<<std::setprecision(12)<<kt[i]<<'\n';raw<<names[m]<<",e2e,"<<i<<','<<et[i]<<'\n';}s<<names[m]<<','<<n<<','<<std::setprecision(12)<<median(kt)<<','<<median(et)<<','<<double(corr)/n<<','<<nf<<','<<sum<<'\n';printf("%s n=%zu kernel=%.3f e2e=%.3f corr=%.4f nf=%zu\n",names[m],n,median(kt),median(et),double(corr)/n,nf);}cudaHostUnregister(ho.data());cudaHostUnregister(c.data());cudaFree(o);cudaFree(d);}
